def signed_log(x):return np.sign(x)*np.log1p(np.abs(x))

def switches(mask):
    if not isinstance(mask,str) or len(mask)!=6 or set(mask)-{'0','1'}:
        raise ValueError('Expected six-bit configuration')
    return tuple(v=='1' for v in mask)

def supervised_pipeline(family,mask):
    a,b,c,d,e,f=switches(mask); steps=[]
    if family=='classification' and a:
        steps.append(('signed_log',FunctionTransformer(signed_log)))
    if b:
        steps.append(('scale',RobustScaler() if family=='regression' and f else StandardScaler()))
    if family=='classification':
        if e:steps.append(('selection',SelectPercentile(f_classif,percentile=50)))
        if f:steps.append(('pca',PCA(n_components=.95,svd_solver='full')))
        steps.append(('model',LogisticRegression(C=.05 if d else 1.,class_weight='balanced' if c else None,
                                                      solver='lbfgs',max_iter=3000,random_state=17)))
        return Pipeline(steps)
    if c:steps.append(('poly',PolynomialFeatures(2,include_bias=False,interaction_only=e)))
    steps.append(('model',Ridge(alpha=10. if d else 1.,solver='svd')))
    model=Pipeline(steps)
    return TransformedTargetRegressor(regressor=model,func=np.log1p,inverse_func=np.expm1) if a else model
